  "dataZone": <String, String>{"en": "Data zone", "it": "Zona dati", "es": "Zona de datos", "fr": "Zone de données", "pt": "Zona de dados"},
  "howItWorks": <String, String>{"en": "How it works", "it": "Come funziona", "es": "Cómo funciona", "fr": "Comment ça marche", "pt": "Como funciona"},
  "localFirstHow": <String, String>{"en": "• The app always saves on the device first.\n• Changes are queued even without Internet.\n• When cloud is available again, only changed items are synced.\n• Private agenda and Noi ♡ remain separate archives.", "it": "• L’app salva sempre prima sul dispositivo.\n• Le modifiche vengono messe in coda anche senza Internet.\n• Quando il cloud torna disponibile, vengono sincronizzati solo gli elementi cambiati.\n• Agenda privata e Noi ♡ restano archivi separati.", "es": "• La app siempre guarda primero en el dispositivo.\n• Los cambios se ponen en cola incluso sin Internet.\n• Cuando vuelve la nube, solo se sincronizan los elementos modificados.\n• La agenda privada y Noi ♡ siguen siendo archivos separados.", "fr": "• L’app enregistre toujours d’abord sur l’appareil.\n• Les modifications sont mises en file même sans Internet.\n• Quand le cloud revient, seuls les éléments modifiés sont synchronisés.\n• L’agenda privé et Noi ♡ restent des archives séparées.", "pt": "• A app guarda sempre primeiro no dispositivo.\n• As alterações ficam em fila mesmo sem Internet.\n• Quando a cloud regressa, apenas os elementos alterados são sincronizados.\n• A agenda privada e Noi ♡ continuam arquivos separados."},
  "privateDefaultCloud": <String, String>{"en": "Private remains the default. Noi ♡ items are shared only when you explicitly choose it.", "it": "Privato resta l’impostazione predefinita. Gli elementi Noi ♡ sono condivisi solo quando lo scegli esplicitamente.", "es": "Privado sigue siendo la opción predeterminada. Los elementos Noi ♡ solo se comparten cuando lo eliges explícitamente.", "fr": "Privé reste le choix par défaut. Les éléments Noi ♡ ne sont partagés que lorsque tu le choisis explicitement.", "pt": "Privado continua a ser a predefinição. Os elementos Noi ♡ só são partilhados quando o escolhes explicitamente."},
  "myAccount": <String, String>{"en": "My account", "it": "Il mio account", "es": "Mi cuenta", "fr": "Mon compte", "pt": "A minha conta"},
  "cloudReadyNotConnected": <String, String>{"en": "Cloud ready, but not connected yet", "it": "Cloud pronto, ma non ancora collegato", "es": "Nube lista, pero aún no conectada", "fr": "Cloud prêt, mais pas encore connecté", "pt": "Cloud pronta, mas ainda não ligada"},
  "cloudBuildNoCredentials": <String, String>{"en": "This build does not contain the project cloud credentials yet. The app keeps working fully offline and no data is lost.", "it": "Questa build non contiene ancora le credenziali del progetto cloud. L’app continua a funzionare completamente offline e nessun dato viene perso.", "es": "Esta compilación aún no contiene las credenciales del proyecto en la nube. La app sigue funcionando completamente sin conexión y no se pierde ningún dato.", "fr": "Cette build ne contient pas encore les identifiants du projet cloud. L’app continue de fonctionner entièrement hors ligne et aucune donnée n’est perdue.", "pt": "Esta build ainda não contém as credenciais do projeto cloud. A app continua a funcionar totalmente offline e nenhum dado é perdido."},
  "sharedPrepared": <String, String>{"en": "The sync structure and database are already prepared for the shared space too.", "it": "La struttura di sincronizzazione e il database sono già predisposti anche per lo spazio condiviso.", "es": "La estructura de sincronización y la base de datos ya están preparadas también para el espacio compartido.", "fr": "La structure de synchronisation et la base de données sont déjà prêtes aussi pour l’espace partagé.", "pt": "A estrutura de sincronização e a base de dados já estão preparadas também para o espaço partilhado."},
  "signInAccount": <String, String>{"en": "Sign in to your account", "it": "Accedi al tuo account", "es": "Inicia sesión en tu cuenta", "fr": "Connecte-toi à ton compte", "pt": "Inicia sessão na tua conta"},
  "googlePrimary": <String, String>{"en": "Google is the main sign-in for Anna's Diary. Email/password sign-in remains available for existing accounts.", "it": "Google è l’accesso principale di Anna's Diary. Il login email/password resta disponibile per gli account esistenti.", "es": "Google es el acceso principal de Anna's Diary. El inicio con email/contraseña sigue disponible para cuentas existentes.", "fr": "Google est la connexion principale d’Anna's Diary. La connexion e-mail/mot de passe reste disponible pour les comptes existants.", "pt": "Google é o acesso principal do Anna's Diary. O login email/palavra-passe continua disponível para contas existentes."},
  "existingEmailAccount": <String, String>{"en": "Existing email account", "it": "Account email esistente", "es": "Cuenta de email existente", "fr": "Compte e-mail existant", "pt": "Conta de email existente"},
  "deletePermanentNote": <String, String>{"en": "Account deletion is permanent and requires explicit confirmation.", "it": "L’eliminazione dell’account è permanente e richiede una conferma esplicita.", "es": "La eliminación de la cuenta es permanente y requiere confirmación explícita.", "fr": "La suppression du compte est définitive et exige une confirmation explicite.", "pt": "A eliminação da conta é permanente e exige confirmação explícita."},
  "accountDeleted": <String, String>{"en": "Account and data permanently deleted.", "it": "Account e dati eliminati definitivamente.", "es": "Cuenta y datos eliminados definitivamente.", "fr": "Compte et données supprimés définitivement.", "pt": "Conta e dados eliminados permanentemente."},
  "accountSignedOut": <String, String>{"en": "Account disconnected. Its data remains stored on the device but is no longer shown.", "it": "Account disconnesso. I dati dell’account restano salvati sul dispositivo ma non sono più mostrati.", "es": "Cuenta desconectada. Sus datos siguen guardados en el dispositivo pero ya no se muestran.", "fr": "Compte déconnecté. Ses données restent enregistrées sur l’appareil mais ne sont plus affichées.", "pt": "Conta desligada. Os respetivos dados continuam guardados no dispositivo, mas já não são mostrados."},
  "pendingSafe": <String, String>{"en": "Local data is safe: {count} changes are waiting for the network.", "it": "I dati locali sono al sicuro: {count} modifiche restano in attesa di rete.", "es": "Los datos locales están seguros: {count} cambios esperan la red.", "fr": "Les données locales sont en sécurité : {count} modifications attendent le réseau.", "pt": "Os dados locais estão seguros: {count} alterações aguardam a rede."},
  "emailPasswordRequired": <String, String>{"en": "Enter email and password.", "it": "Inserisci email e password.", "es": "Introduce email y contraseña.", "fr": "Saisis l’e-mail et le mot de passe.", "pt": "Introduz email e palavra-passe."},
  "connectedSynced": <String, String>{"en": "Account connected and synced.", "it": "Account connesso e sincronizzato.", "es": "Cuenta conectada y sincronizada.", "fr": "Compte connecté et synchronisé.", "pt": "Conta ligada e sincronizada."},
  "emailRequired": <String, String>{"en": "Enter your account email first.", "it": "Inserisci prima l’email del tuo account.", "es": "Introduce primero el correo de tu cuenta.", "fr": "Saisis d’abord l’e-mail de ton compte.", "pt": "Introduz primeiro o email da tua conta."},
  "deleteAccountBody": <String, String>{"en": "This permanently deletes your cloud account and linked data. It cannot be undone.", "it": "Questa operazione elimina definitivamente il tuo account cloud e i dati collegati. Non può essere annullata.", "es": "Esta operación elimina definitivamente tu cuenta en la nube y los datos vinculados. No se puede deshacer.", "fr": "Cette opération supprime définitivement ton compte cloud et les données associées. Elle est irréversible.", "pt": "Esta operação elimina permanentemente a tua conta cloud e os dados associados. Não pode ser anulada."},
  "deleteOwnerWarning": <String, String>{"en": "If you own a Noi ♡ space, that space is also deleted for the other members. The local Private Vault remains separate.", "it": "Se sei proprietario di uno spazio Noi ♡, quello spazio viene eliminato anche per gli altri membri. La Cassaforte privata locale resta separata.", "es": "Si eres propietario de un espacio Noi ♡, ese espacio también se elimina para los demás miembros. La Caja fuerte privada local permanece separada.", "fr": "Si tu es propriétaire d’un espace Noi ♡, cet espace est aussi supprimé pour les autres membres. Le Coffre privé local reste séparé.", "pt": "Se fores proprietário de um espaço Noi ♡, esse espaço também é eliminado para os outros membros. O Cofre privado local permanece separado."},
  "exportBeforeDelete": <String, String>{"en": "Before continuing, you can create an export from Backup.", "it": "Prima di continuare puoi creare un export dalla sezione Backup.", "es": "Antes de continuar, puedes crear una exportación desde Copia de seguridad.", "fr": "Avant de continuer, tu peux créer un export depuis Sauvegarde.", "pt": "Antes de continuar, podes criar uma exportação em Backup."},
  "typeDelete": <String, String>{"en": "Type DELETE to confirm.", "it": "Scrivi DELETE per confermare.", "es": "Escribe DELETE para confirmar.", "fr": "Écris DELETE pour confirmer.", "pt": "Escreve DELETE para confirmar."},
  "accountCloudDeletedLocalFailed": <String, String>{"en": "The cloud account was deleted, but local cleanup did not complete. Restart the app before using it again.", "it": "Account eliminato dal cloud, ma la pulizia locale non è stata completata. Riavvia l’app prima di usarla di nuovo.", "es": "La cuenta se eliminó de la nube, pero la limpieza local no se completó. Reinicia la app antes de volver a usarla.", "fr": "Le compte cloud a été supprimé, mais le nettoyage local n’est pas terminé. Redémarre l’app avant de la réutiliser.", "pt": "A conta foi eliminada da cloud, mas a limpeza local não foi concluída. Reinicia a app antes de a voltares a usar."},
  "cloudConnectedDescription": <String, String>{"en": "Your personal agenda can stay aligned across Android, iPhone and Web.", "it": "La tua agenda personale può restare allineata su Android, iPhone e Web.", "es": "Tu agenda personal puede mantenerse sincronizada entre Android, iPhone y Web.", "fr": "Ton agenda personnel peut rester synchronisé entre Android, iPhone et le Web.", "pt": "A tua agenda pessoal pode manter-se sincronizada entre Android, iPhone e Web."},
